                  mig1Content: "انسَ نصوص SQL اليدوية. تستخدم NEXORA ترحيلات (Code-First Migrations) في EF Core، وتقوم تلقائياً بإنشاء بناء جملة محدد للمزود الذي اخترته.",
                  mig1Title: "توليد تلقائي متعدد المخططات",
                  mig2Content: "انشر تغييرات المخطط بثقة عبر بيئات التطوير، والتجهيز (Staging)، والإنتاج باستخدام حزم الترحيل المعزولة حتمياً الخاصة بنا.",
                  mig2Title: "عمليات نشر حتمية",
                  mig3Content: "تتبع عمليات الترحيل المطبقة في جدول سجل مخصص، مما يضمن عدم محاولة المجموعات الموزعة تعديل المخطط بشكل متزامن.",
                  mig3Title: "ترقيات متزامنة آمنة",
                  mig4Content: "بالنسبة لإعادة هيكلة المخططات المعقدة، توفر NEXORA خطافات (Hooks) ما قبل وما بعد الترحيل مما يسمح بتحويل البيانات دون أي فترة توقف (Zero-Downtime).",
                  mig4Title: "تحويلات بدون فترات توقف",
                  migrationContent: "يقيّم محرك النشر حالة قاعدة البيانات الحالية ويطبق العمليات المعلقة تلقائياً عند التمهيد. يتم إجراء كل ترحيل في معاملة (Transaction) — إما أن تتم ترقية المخطط بالكامل بشكل مثالي، أو يتراجع النظام بأمان.",
                  migrationTitle: "تطورات المخطط في معاملات (Transacted)",
                  perfTitle: "تجميع الاستعلام المحسّن",
                  providersIntro: "تتعامل NEXORA مع قاعدة البيانات كطبقة استمرار قابلة للتبديل (Interchangeable). يعزل نمط المستودع (Repository Pattern) الخاص بنا المنطق الخاص بالمزود بشكل نظيف.",
                  providersTitle: "محركات نشر محايدة",
                  switchContent: "قم بتبديل مزودي قواعد البيانات عبر سطر واحد في appsettings.json. بدّل بين وضع قاعدة البيانات الموحدة (جميع الوحدات تشترك في قاعدة بيانات واحدة) ووضع قواعد البيانات المتعددة (كل وحدة لها قاعدة بياناتها الخاصة) باستخدام إعداد Database.Mode. انتقل من نسخة PostgreSQL واحدة في التطوير إلى قواعد بيانات Oracle RAC معزولة لكل وحدة في الإنتاج — بسلاسة تامة.",
                  switchTitle: "تبديل المزود بدون احتكاك",
                  tip: "نصيحة: لعمليات نشر الخدمات المصغرة، فكر في استخدام مزودي قواعد بيانات مختلفين لسياقات محددة (Bounded Contexts) مختلفة بناءً على ملفات تعريف الأداء الفريدة الخاصة بها.",
                  title: "حيادية قاعدة البيانات",
