                  integrationContent: "هل تحتاج إلى مزامنة البيانات مع Salesforce أو SAP أو نظام AS400 القديم؟ نحن نوفر محولات تكامل جاهزة للاستخدام ومرنة للغاية باستخدام Apache Kafka أو Azure Service Bus لسد الفجوة بسلاسة.",
                  integrationTitle: "عمليات التكامل مع الأنظمة القديمة (Legacy Systems)",
                  intro: "بينما تتمتع NEXORA بقوة هائلة بشكل افتراضي، فإن المؤسسات الكبرى غالباً ما تتطلب خدمات متميزة. توفر باقة المؤسسات (Enterprise Tier) ساعات هندسية مخصصة، ودعماً متقدماً لقواعد البيانات، ووحدات أعمال متخصصة.",
