                  intro: "لا يمكن أن يكون الأمان فكرة لاحقة تُربط بطبقة التطبيق (Application layer). تقوم NEXORA بتقوية المحيط عند مستوى البنية التحتية، وإنشاء درع هائل ضد هجمات DDoS الحجمية، والبرمجة عبر المواقع (XSS)، وعبور الشبكة (Network traversal) غير المصرح به.",
