                  networkSegment: "التقسيم الدقيق (Micro-Segmentation)",
                  networkSegmentDesc: "عزل قواعد البيانات وعمال الخلفية (Background workers) في شبكات فرعية خاصة غير قابلة للتوجيه ومنفصلة تماماً عن الإنترنت العام.",
