                  rateLimitContent: "تحمل الارتفاعات المفاجئة في حركة المرور وعمليات المسح العنيف (Brute-force). تتضمن NEXORA نظام تحديد معدل موزع مدعوم بـ Redis يقوم ديناميكياً بخنق (Throttling) عناوين IP المسيئة أو رموز JWT المحددة قبل أن تتمكن من استنفاد تجمعات اتصالات قاعدة البيانات (Connection pools).",
