                  circuitContent: "إذا توقفت بوابة دفع تابعة لجهة خارجية عن الاتصال، فإن قواطع الدائرة (Circuit Breakers) الخاصة بـ NEXORA 'تفصل' فوراً بعد حدٍ مُكوَّن من الإخفاقات. هذا يمنع تطبيقك مادياً من إرسال آلاف الطلبات المحكوم عليها بالفشل، مما يتيح للخدمة الخارجية وقتاً للتعافي بينما يفشل تطبيقك بسرعة (Fails fast).",
                  circuitTitle: "قواطع الدائرة الآلية (Circuit Breakers)",
                  configTitle: "تكوين السياسات الديناميكي",
                  degradationContent: "عندما تفشل تبعية خارجية، لا يتعطل النظام — بل يتدهور بأناقة (Degrades elegantly). إذا كانت واجهة برمجة تطبيقات أسعار الشحن المباشرة غير قابلة للوصول، فإن NEXORA تقدم تلقائياً آخر الأسعار المعروفة المخبأة مؤقتاً (Cached)، مما يضمن بقاء تدفقات الدفع (Checkout) دون انقطاع.",
                  degradationTitle: "تدهور أنيق وسلس (Graceful Degradation)",
