                  fieldContent: "أدوار النظام القياسية (مثل 'Tenant_Admin') مقفلة فعلياً ولا يمكن للمستخدمين النهائيين حذفها أو تكوينها بشكل خاطئ وكارثي، مما يضمن استقرار المنصة الأساسي.",
                  fieldTitle: "أدوار نظام غير قابلة للتغيير (Immutable)",
                  intro: "في بيئة B2B SaaS، تعتبر 'المسؤول' و'المستخدم' أدواراً غير كافية على الإطلاق. توفر NEXORA محرك أدوار وصلاحيات دقيق للغاية ومتعدد المستأجرين بطبيعته يتيح لعملاء المؤسسات لديك رسم خريطة واضحة لوصول النظام إلى تسلسلاتهم الهرمية المعقدة للشركات.",
                  rbacContent: "بدلاً من كتابة فحوصات أدوار صلبة (مثل `if (user.Role == 'Admin')`)، تتحقق NEXORA من القدرات الدقيقة (`[HasPermission(Permissions.Invoices.Delete)]`). هذا يفصل منطق تفويض الأعمال الخاص بك تماماً عن الطبيعة المتغيرة باستمرار للمسميات الوظيفية.",
                  rbacTitle: "التفويض القائم على القدرات (Capability-Based Authorization)",
                  roleCloning: "استنساخ الأدوار بدون احتكاك",
                  roleCloningDesc: "يمكن للمسؤولين استنساخ مصفوفات الصلاحيات المعقدة على الفور لإنشاء أدوار أقسام جديدة بسرعة.",
                  roleHierarchy: "الوراثة المقيدة بالنطاق (Scope-Restricted Inheritance)",
                  roleHierarchyDesc: "منع تصعيد الامتيازات (Escalation of privilege) عن طريق ضمان استحالة قيام المستخدمين رياضياً بمنح صلاحيات لا يمتلكونها.",
                  tenantScoped: "أدوار معزولة بالمستأجر",
                  tenantScopedDesc: "تكوينات الأدوار تنتمي حصرياً إلى المستأجر (Tenant). إن 'المدير' في المستأجر A يمتلك حدوداً مختلفة تماماً عن 'المدير' في المستأجر B.",
                  // User Groups
                  userGroupsTitle: "التخصيص المجمع المبني على المجموعات",
                  userGroupsContent: "توقف عن تخصيص الأدوار لكل مسؤول على حدة. تتيح لك ميزة مجموعات المستخدمين (User Groups) في NEXORA إنشاء مجموعات مسماة، وتعيين أدوار وقيود على مستوى الحقل (Field-level) للمجموعة، ثم إضافة المسؤولين كأعضاء. يرث جميع الأعضاء على الفور صلاحيات المجموعة عند تسجيل الدخول التالي — مع القوة الكاملة للدمج الإضافي وتطبيق قيود مستوى الحقل.",
                  groupBatchAssign: "تخصيص فوري لأسطول من المستخدمين",
                  groupBatchAssignDesc: "تخصيص أدوار ومصفوفات قيود معقدة لمئات المسؤولين في وقت واحد عبر عضوية المجموعة المسماة.",
                  groupRestrictions: "قيود حقول على مستوى المجموعة",
                  groupRestrictionsDesc: "تحديد قيود الحقل لكل صلاحية (Per-permission) على مستوى المجموعة. يتم دمج القيود إضافياً مع قيود الدور المباشرة عند تسجيل الدخول.",
                  groupTenantScoped: "مجموعات محددة بنطاق المستأجر (Tenant-Scoped)",
                  groupTenantScopedDesc: "كل مجموعة تنتمي إلى مستأجر واحد بالضبط. يدير مسؤولو المستأجر مجموعاتهم بينما يرى المشرفون الفائقون (SuperAdmins) جميع المجموعات عالمياً.",
                  groupAdditiveMerge: "دمج أمني إضافي (Additive)",
                  groupAdditiveMergeDesc: "أدوار المجموعة توسع الصلاحيات الفعلية. وتتضاعف قيود المجموعة مع القيود المباشرة — والمنع (Deny) يفوز دائماً.",
                  title: "التحكم الدقيق في الوصول",
