                  zeroLatencyTitle: "تقييم بصفر تأخير (Zero-Latency)",
                  zeroLatencyDesc: "يتم تجميع المجموعات والأدوار والقيود مسبقاً وتسطيحها (Flattened) مباشرة في حمولة JWT (Payload)، مما لا يسبب أي عمليات بحث في قاعدة البيانات أثناء فحوصات ترخيص API في وقت التشغيل.",
                  tenantIsolationTitle: "عزل مطلق للمستأجر (Absolute Tenant Isolation)",
                  tenantIsolationDesc: "مجموعات المستخدمين مرتبطة بصرامة بمعرّف المستأجر المحلّل. لا يمكن معمارياً حدوث تلوث في المجموعات عبر المستأجرين في ظل عوامل تصفية الاستعلام العامة (Global Query Filters) الخاصة بـ EF Core.",
                  nukePaveTitle: "المزامنة التدميرية (Nuke-and-Pave)",
                  nukePaveDesc: "تتم معالجة تحديثات حمولة واجهة المستخدم الضخمة (مثل تغيير 50 دوراً) باستخدام خوارزمية (Nuke-and-pave) المعززة التي تتحقق من الحالة بصرامة قبل الالتزام (Commit).",
